// ---- the built-ins ------------------------------------------------------------------------------------------------
// Where a game-styled row looks for the player's own copy of the real font, in order (the first found wins):
//   MODS   a file in mods/fonts: a lower-case name, "*" at the end = any name starting so (TTF: .ttf / .otf)
//   SYSTEM a path on this computer; "win:" / "mac:" / "linux:" first = only there; %WINDIR% and ~ expanded
//   STEAM  a path inside every Steam library (the default one and steamapps/libraryfolders.vdf's)
enum Where : uint8_t { MODS, SYSTEM, STEAM };
enum Fmt : uint8_t { TTF, QUAKE };   // QUAKE: Quake's CONCHARS (a PAK, gfx.wad, conchars.lmp or a sheet picture)
struct Real { Where where; Fmt fmt; const char* path; };
struct Builtin {
    const char* id;        // the ui_font value (stable: saved in quark.cfg)
    const char* name;      // the menu's name for the bundled font
    const char* baked;     // its atlas in font_builtin.h (kBakedFonts' id); "" = font_ui.h's (the default)
    const char* hint;      // the grey line with the bundled font ("" = none)
    const char* override;  // the owner's asset override that replaces the bundled font (docs/ASSETS.md), or null
    const char* realName;  // the menu's name when the player's own real font is used
    Real real[8];          // ...and where to look for it (path null = end)
};
